CREATE TABLE IF NOT EXISTS customer_opening_balances (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT UNSIGNED NOT NULL, opening_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, notes VARCHAR(255), created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE OR REPLACE VIEW customer_ledger AS SELECT s.customer_id, s.sale_date entry_date, s.sale_no reference, 'Credit sale' description, s.total debit, 0 credit FROM sales s WHERE s.payment_type='credit' AND s.status NOT IN ('cancelled','returned') UNION ALL SELECT p.customer_id, p.payment_date, p.receipt_no, 'Customer payment', 0, p.amount FROM customer_payments p UNION ALL SELECT o.customer_id,o.opening_date,CONCAT('OPEN-',o.id),'Opening credit balance',o.amount,0 FROM customer_opening_balances o;
